def topo_sort(graph):
    visited = set()
    path_stack = set()
    result = []

    # Collect all nodes, including those appearing only as dependencies
    all_nodes = set()
    for node, deps in graph.items():
        all_nodes.add(node)
        all_nodes.update(deps)

    def dfs(node):
        if node in path_stack:
            return False # Cycle detected
        if node in visited:
            return True  # Already processed

        path_stack.add(node)
        for dep in graph.get(node, []):
            if not dfs(dep):
                return False
        path_stack.remove(node)
        visited.add(node)
        result.append(node)
        return True

    for node in all_nodes:
        if node not in visited:
            if not dfs(node):
                return None

    return result
```

