import re

def parse_duration(s):
    s = s.strip()
    if not s:
        raise ValueError("Unparseable input")

    valid_chars = set("0123456789dhms")
    if not all(c in valid_chars for c in s):
        raise ValueError("Unparseable input")

    matches = re.findall(r'(\d+)([dhms])', s)
    if not matches:
        raise ValueError("Unparseable input")

    # Ensure no valid characters remain unparsed
    if s != "".join(d + u for d, u in matches):
        raise ValueError("Unparseable input")

    units = {
        'd': 86400,
        'h': 3600,
        'm': 60,
        's': 1
    }

    return sum(int(d) * units[u] for d, u in matches)
```

