module.exports = function debounceCount(fn, ms) {
    let timer = null;
    let pendingArgs = null;
    let pendingThis = null;

    const call = function (...args) {
        clearTimeout(timer);
        pendingArgs = args;
        pendingThis = this;
        timer = setTimeout(() => {
            fn.apply(pendingThis, pendingArgs);
        }, ms);
    };

    const flush = function () {
        clearTimeout(timer);
        if (pendingArgs !== null) {
            fn.apply(pendingThis, pendingArgs);
            pendingArgs = null;
            pendingThis = null;
        }
    };

    return { call, flush };
};

