function mergeDeep(a, b) {
  if (b == null) return a;
  if (a == null) return b;

  // Handle arrays separately to support deep merging of list elements
  if (Array.isArray(a) && Array.isArray(b)) {
    const result = [];
    const maxLen = Math.max(a.length, b.length);
    for (let i = 0; i < maxLen; i++) {
      result[i] = mergeDeep(a[i], b[i]);
    }
    return result;
  }

  // If types mismatch (one primitive, one object/array, or both primitives), return b
  const isPlainObject = (val) => val !== null && typeof val === 'object' && !Array.isArray(val);
  if (!isPlainObject(a) || !isPlainObject(b)) {
    return b;
  }

  // Handle plain objects
  const target = {};
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  for (let key of keys) {
    const valA = a[key];
    const valB = b[key];
    if (isPlainObject(valA) && isPlainObject(valB)) {
      target[key] = mergeDeep(valA, valB);
    } else {
      target[key] = valB !== undefined ? valB : valA;
    }
  }
  return target;
}

module.exports = mergeDeep;
```

