function rotateArray(arr, k) {
    const n = arr.length;
    if (n === 0) return [];

    // Normalize k to positive range [0, n-1]
    let effectiveK = k % n;
    if (effectiveK < 0) {
        effectiveK += n;
    }

    const sliceStart = n - effectiveK;
    const leftPart = arr.slice(sliceStart);
    const rightPart = arr.slice(0, sliceStart);

    return [...leftPart, ...rightPart];
}

module.exports = rotateArray;
```

