function deepClone(v) {
    if (v === null || typeof v !== 'object') {
        return v;
    }

    // Handle circular references to prevent infinite recursion
    if (Object.prototype.toString.call(v) === '[object Object]' && circular.has(v)) {
        return v;
    }
    if (Array.isArray(v) && circular.has(v)) {
        return v;
    }

    circular.add(v);

    let clone = Array.isArray(v) ? [] : {};

    if (Array.isArray(v)) {
        v.forEach(item => clone.push(deepClone(item)));
    } else {
        for (const key in v) {
            if (v.hasOwnProperty(key)) {
                clone[key] = deepClone(v[key]);
            }
        }
    }

    circular.delete(v);
    return clone;
}

const circular = new WeakSet();
module.exports = { deepClone };
```

