export function maxBy<T>(arr: T[], f: (t: T) => number): T | undefined {
  if (arr.length === 0) {
    return undefined;
  }
  let max: T = arr[0];
  let maxVal: number = f(max);
  for (let i = 1; i < arr.length; i++) {
    const val = f(arr[i]);
    if (val > maxVal) {
      maxVal = val;
      max = arr[i];
    }
  }
  return max;
}
