import React, { useState, useCallback } from 'react';
import { FlatList, Text, View, StyleSheet } from 'react-native';

// Mock function to simulate data fetching
const fetchMoreData = (page, setMore) => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const count = 10;
      const newData = Array.from({ length: count }, (_, i) => ({
        id: (page * count) + i,
        text: `Item ${(page * count) + i}`,
      }));
      setMore((prev) => [...prev, ...newData]);
      resolve(newData);
    }, 1000);
  });
};

const InfiniteScrollList = () => {
  const [data, setData] = useState([]);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);

  const loadMore = useCallback(async () => {
    if (loading || !hasMore) return;

    setLoading(true);
    // Simulate API call
    const newData = await fetchMoreData(page, setData);

    setPage((prev) => prev + 1);

    // Stop after 10 pages for this demo
    if (page >= 10) {
      setHasMore(false);
    }

    setLoading(false);
  }, [loading, hasMore, page]);

  const onEndReached = useCallback(() => {
    loadMore();
  }, [loadMore]);

  return (
    <FlatList
      data={data}
      keyExtractor={(item) => item.id.toString()}
      renderItem={({ item }) => (
        <View style={styles.card}>
          <Text style={styles.text}>{item.text}</Text>
        </View>
      )}
      onEndReached={onEndReached}
      onEndReachedThreshold={'visible'} // Or '30%' or a number like 100
      ListHeaderComponent={<Text style={styles.header}>Infinite Scroll</Text>}
      ListFooterComponent={
        loading 
