import { Linking } from 'react-native';

export default function ExternalLinkOpener() {
  const [loading, setLoading] = useState(false);

  const openUrl = async (url) => {
    try {
      if (loading) return;
      setLoading(true);

      const canOpen = await Linking.canOpenURL(url);

      if (canOpen) {
        await Linking.openURL(url);
      } else {
        Alert.alert('Error', 'No app capable of handling this URL was found.');
      }
    } catch (error) {
      console.error('Error opening URL', error);
      Alert.alert('Error', 'Failed to open URL.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <View style={styles.container}>
      <Text>External Link Component</Text>
      <Button
        title={loading ? 'Opening...' : 'Open URL'}
        onPress={() => openUrl('https://example.com')}
        disabled={loading}
      />
    </View>
  );
}

