import React, { useState, useRef } from 'react';
import {
  View,
  Text,
  ScrollView,
  StyleSheet,
} from 'react-native';
import { Dimensions, Platform, View as RNView } from 'react-native';
import { useScroll } from 'react-native-reanimated';

// This is a common solution using React Native Reanimated for paging
// However, for a pure ScrollView implementation, here is a custom logic approach

const HorizontalScrollViewWithPaging = ({ children }) => {
  const scrollRef = useRef(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const { node, scrollX, index, width } = useScroll(scrollRef);

  const scrollWidth = useRef(0);
  const itemWidth = useRef(0);

  React.useEffect(() => {
    const handleSizeChange = () => {
      if (Platform.OS === 'android') {
        const { width: screenWidth } = Dimensions.get('window');
        itemWidth.current = screenWidth - 16;
      }
    };
    handleSizeChange();
    Dimensions.addEventListener('change', handleSizeChange);
  }, []);

  return (
    <ScrollView
      ref={scrollRef}
      onMomentumScrollEnd={(e) => {
        // Calculate scroll position to find nearest index
        const scrollX = e.nativeEvent.contentOffset.x;
        const index = Math.round(scrollX / itemWidth.current);
        setCurrentIndex(index);
      }}
      horizontal={true}
      pagingEnabled={Platform.OS === 'ios' ? true : false} 
      scrollEnabled={Platform.OS === 'ios'}
      contentContainerStyle={{ paddingHorizontal: 10 }}
      showsHorizontalScrollIndicator={false}
      onScroll={(e) => {
         // Reanimated could be used here for smoother snapping
      }}
    >
      {children}
    </ScrollView>
  );
};

export default HorizontalScrollViewWithPaging;
